import { spawnSync } from 'node:child_process';
const python = process.platform === 'win32' ? 'python' : 'python3';
for (const [command, args] of [[process.execPath, ['--test', 'test/vue-client.test.mjs']], [python, ['-m', 'unittest', 'backend/test_cms_service.py']]]) {
  const result = spawnSync(command, args, { encoding: 'utf8', stdio: 'inherit', shell: false });
  if (result.error) throw result.error;
  if (result.status !== 0) process.exit(result.status ?? 1);
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { createCmsClient } from '../web/vue/cms-client.js';

test('Vue-facing client follows the injected HTTP contract', async () => {
  const calls = [];
  const http = {
    get: async (...args) => { calls.push(['get', ...args]); return { data: [{ slug: 'news' }] }; },
    post: async (...args) => { calls.push(['post', ...args]); return { data: { slug: args[1].slug, published: true } }; }
  };
  const client = createCmsClient(http);
  assert.deepEqual(await client.listPublished(), [{ slug: 'news' }]);
  assert.deepEqual(await client.publish('launch', 'Launch', 'Hello'), { slug: 'launch', published: true });
  assert.deepEqual(calls, [
    ['get', '/api/articles?status=published'],
    ['post', '/api/articles', { slug: 'launch', title: 'Launch', body: 'Hello' }]
  ]);
});
